class CommitResult:
    def __init__(self):
        raise RuntimeError("CommitResult cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    class FINISHED:
        outcome: "ExtractionOutcome"

        def __init__(self,outcome: "ExtractionOutcome"):
            self.outcome = outcome

        def __str__(self):
            return "CommitResult.FINISHED(outcome={})".format(self.outcome)

        def __eq__(self, other):
            if not other.is_finished():
                return False
            if self.outcome != other.outcome:
                return False
            return True
    
    class NEEDS_DECISION:
        summary: "ConflictSummary"

        def __init__(self,summary: "ConflictSummary"):
            self.summary = summary

        def __str__(self):
            return "CommitResult.NEEDS_DECISION(summary={})".format(self.summary)

        def __eq__(self, other):
            if not other.is_needs_decision():
                return False
            if self.summary != other.summary:
                return False
            return True
    
    

    # For each variant, we have an `is_NAME` method for easily checking
    # whether an instance is that variant.
    def is_finished(self) -> bool:
        return isinstance(self, CommitResult.FINISHED)
    def is_needs_decision(self) -> bool:
        return isinstance(self, CommitResult.NEEDS_DECISION)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
CommitResult.FINISHED = type("CommitResult.FINISHED", (CommitResult.FINISHED, CommitResult,), {})  # type: ignore
CommitResult.NEEDS_DECISION = type("CommitResult.NEEDS_DECISION", (CommitResult.NEEDS_DECISION, CommitResult,), {})  # type: ignore




class _UniffiConverterTypeCommitResult(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return CommitResult.FINISHED(
                _UniffiConverterTypeExtractionOutcome.read(buf),
            )
        if variant == 2:
            return CommitResult.NEEDS_DECISION(
                _UniffiConverterTypeConflictSummary.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_finished():
            _UniffiConverterTypeExtractionOutcome.check_lower(value.outcome)
            return
        if value.is_needs_decision():
            _UniffiConverterTypeConflictSummary.check_lower(value.summary)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_finished():
            buf.write_i32(1)
            _UniffiConverterTypeExtractionOutcome.write(value.outcome, buf)
        if value.is_needs_decision():
            buf.write_i32(2)
            _UniffiConverterTypeConflictSummary.write(value.summary, buf)







