class VfsSessionStatus:
    """
    Non-blocking algebraic session status returned by `open_archive_session`.
    """

    def __init__(self):
        raise RuntimeError("VfsSessionStatus cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    class READY:
        session: "VfsSession"
        has_encrypted_entries: "bool"

        def __init__(self,session: "VfsSession", has_encrypted_entries: "bool"):
            self.session = session
            self.has_encrypted_entries = has_encrypted_entries

        def __str__(self):
            return "VfsSessionStatus.READY(session={}, has_encrypted_entries={})".format(self.session, self.has_encrypted_entries)

        def __eq__(self, other):
            if not other.is_ready():
                return False
            if self.session != other.session:
                return False
            if self.has_encrypted_entries != other.has_encrypted_entries:
                return False
            return True
    
    class PASSWORD_REQUIRED:
        challenge: "EncryptedHeaderChallenge"

        def __init__(self,challenge: "EncryptedHeaderChallenge"):
            self.challenge = challenge

        def __str__(self):
            return "VfsSessionStatus.PASSWORD_REQUIRED(challenge={})".format(self.challenge)

        def __eq__(self, other):
            if not other.is_password_required():
                return False
            if self.challenge != other.challenge:
                return False
            return True
    
    class MISSING_VOLUME:
        descriptor: "VfsMissingVolumeDescriptor"

        def __init__(self,descriptor: "VfsMissingVolumeDescriptor"):
            self.descriptor = descriptor

        def __str__(self):
            return "VfsSessionStatus.MISSING_VOLUME(descriptor={})".format(self.descriptor)

        def __eq__(self, other):
            if not other.is_missing_volume():
                return False
            if self.descriptor != other.descriptor:
                return False
            return True
    
    

    # For each variant, we have an `is_NAME` method for easily checking
    # whether an instance is that variant.
    def is_ready(self) -> bool:
        return isinstance(self, VfsSessionStatus.READY)
    def is_password_required(self) -> bool:
        return isinstance(self, VfsSessionStatus.PASSWORD_REQUIRED)
    def is_missing_volume(self) -> bool:
        return isinstance(self, VfsSessionStatus.MISSING_VOLUME)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
VfsSessionStatus.READY = type("VfsSessionStatus.READY", (VfsSessionStatus.READY, VfsSessionStatus,), {})  # type: ignore
VfsSessionStatus.PASSWORD_REQUIRED = type("VfsSessionStatus.PASSWORD_REQUIRED", (VfsSessionStatus.PASSWORD_REQUIRED, VfsSessionStatus,), {})  # type: ignore
VfsSessionStatus.MISSING_VOLUME = type("VfsSessionStatus.MISSING_VOLUME", (VfsSessionStatus.MISSING_VOLUME, VfsSessionStatus,), {})  # type: ignore




class _UniffiConverterTypeVfsSessionStatus(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return VfsSessionStatus.READY(
                _UniffiConverterTypeVfsSession.read(buf),
                _UniffiConverterBool.read(buf),
            )
        if variant == 2:
            return VfsSessionStatus.PASSWORD_REQUIRED(
                _UniffiConverterTypeEncryptedHeaderChallenge.read(buf),
            )
        if variant == 3:
            return VfsSessionStatus.MISSING_VOLUME(
                _UniffiConverterTypeVfsMissingVolumeDescriptor.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_ready():
            _UniffiConverterTypeVfsSession.check_lower(value.session)
            _UniffiConverterBool.check_lower(value.has_encrypted_entries)
            return
        if value.is_password_required():
            _UniffiConverterTypeEncryptedHeaderChallenge.check_lower(value.challenge)
            return
        if value.is_missing_volume():
            _UniffiConverterTypeVfsMissingVolumeDescriptor.check_lower(value.descriptor)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_ready():
            buf.write_i32(1)
            _UniffiConverterTypeVfsSession.write(value.session, buf)
            _UniffiConverterBool.write(value.has_encrypted_entries, buf)
        if value.is_password_required():
            buf.write_i32(2)
            _UniffiConverterTypeEncryptedHeaderChallenge.write(value.challenge, buf)
        if value.is_missing_volume():
            buf.write_i32(3)
            _UniffiConverterTypeVfsMissingVolumeDescriptor.write(value.descriptor, buf)







