    return _UniffiConverterBool.lift(_uniffi_rust_call(_UniffiLib.uniffi_ttzip_engine_fn_func_apfs_clone_file,
        _UniffiConverterString.lower(src),
        _UniffiConverterString.lower(dst),
        _UniffiConverterBool.lower(overwrite)))


